public class LibraryBookCatalog {String title,isbn;LibraryBookCatalog(String t,String i){title=t;isbn=i;}LibraryBookCatalog(String t){this(t,"PENDING");}void print(){System.out.println(title+" | "+isbn+" | Catalogued: true");}public static void main(String[]x){String[]t={"Clean Code","Untitled Draft","1984","Notes"},i={"978-0132350884","","9780451524935",""};for(int k=0;k<t.length;k++){LibraryBookCatalog b=i[k].equals("")?new LibraryBookCatalog(t[k]):new LibraryBookCatalog(t[k],i[k]);b.print();}}}
